package com.aoo.bcg.share;
import org.junit.jupiter.api.Test;import java.sql.*;import java.time.*;import static org.junit.jupiter.api.Assertions.*;
class InviteLinkChannelBindingTest {
 private String create(InviteLinkServiceTest t)throws Exception{t.setup();String token=t.signer.issue();t.repo.create(42,"ROOM",7,Duration.ofMinutes(5),4,token,"original-channel");return t.signer.verify(token);}
 private long count(InviteLinkServiceTest t,String sql)throws Exception{try(Connection c=t.ds.getConnection();Statement s=c.createStatement();ResultSet r=s.executeQuery(sql)){r.next();return r.getLong(1);}}
 @Test void callerCannotReplaceOriginalAttributionAndReplaysDoNotWrite()throws Exception{InviteLinkServiceTest t=new InviteLinkServiceTest();String code=create(t);var first=t.repo.consume(code,77,"channel-key-0001","caller-channel");assertEquals(42,first.issuerId());assertEquals(7,first.targetId());assertEquals("ROOM",first.kind());assertEquals(first.consumptionId(),t.repo.consume(code,77,"channel-key-0001","other").consumptionId());assertEquals(first.consumptionId(),t.repo.consume(code,77,"channel-key-0002","other").consumptionId());t.repo.consume(code,78,"channel-key-0003","other");assertEquals(2,count(t,"SELECT COUNT(*) FROM aoo_invite_consumption"));assertEquals(2,count(t,"SELECT use_count FROM aoo_invite_link"));assertEquals(2,count(t,"SELECT COUNT(*) FROM aoo_invite_link_audit WHERE event_type='CONSUMED' AND source_channel='original-channel'"));assertEquals(2,count(t,"SELECT COUNT(*) FROM aoo_invite_link_audit WHERE event_type='CONSUMED'"));}
 @Test void missingDuplicateAndEmptyCreationRejectWithoutWrites()throws Exception{for(String mode:new String[]{"MISSING","DUPLICATE","NULL","BLANK"}){InviteLinkServiceTest t=new InviteLinkServiceTest();String code=create(t);try(Connection c=t.ds.getConnection();Statement s=c.createStatement()){if(mode.equals("MISSING"))s.executeUpdate("DELETE FROM aoo_invite_link_audit WHERE event_type='CREATED'");else if(mode.equals("DUPLICATE"))s.executeUpdate("INSERT INTO aoo_invite_link_audit(invite_id,event_type,actor_account_id,source_channel,outcome,occurred_at) SELECT invite_id,event_type,actor_account_id,'conflict',outcome,occurred_at FROM aoo_invite_link_audit WHERE event_type='CREATED'");else s.executeUpdate("UPDATE aoo_invite_link_audit SET source_channel="+(mode.equals("NULL")?"NULL":"' '")+" WHERE event_type='CREATED'");}InviteLinkError e=assertThrows(InviteLinkError.class,()->t.repo.consume(code,77,"channel-key-0001","caller"));assertEquals(503,e.status(),mode);assertEquals("INVITE_ATTRIBUTION_UNAVAILABLE",e.code(),mode);assertEquals(0,count(t,"SELECT COUNT(*) FROM aoo_invite_consumption"),mode);assertEquals(0,count(t,"SELECT use_count FROM aoo_invite_link"),mode);assertEquals(0,count(t,"SELECT COUNT(*) FROM aoo_invite_link_audit WHERE event_type='CONSUMED'"),mode);}}
 @Test void historicalReplayAndPreviewRemainDistinctFromAttribution()throws Exception{InviteLinkServiceTest t=new InviteLinkServiceTest();String code=create(t);var first=t.repo.consume(code,77,"channel-key-0001","caller");try(Connection c=t.ds.getConnection();Statement s=c.createStatement()){s.executeUpdate("DELETE FROM aoo_invite_link_audit WHERE event_type='CREATED'");}t.repo.preview(code,"visitor-channel","local","none");assertEquals(first.consumptionId(),t.repo.consume(code,77,"channel-key-0001","other").consumptionId());assertEquals(1,count(t,"SELECT COUNT(*) FROM aoo_invite_link_audit WHERE event_type='PREVIEWED' AND source_channel='visitor-channel'"));assertEquals(1,count(t,"SELECT COUNT(*) FROM aoo_invite_link_audit WHERE event_type='CONSUMED' AND source_channel='original-channel'"));t.repo.revoke(42,first.inviteId(),"caller");assertThrows(InviteLinkError.class,()->t.repo.preview(code,"visitor","local","none"));assertThrows(InviteLinkError.class,()->t.repo.consume(code,78,"channel-key-0002","other"));assertEquals(first.consumptionId(),t.repo.consume(code,77,"channel-key-0001","other").consumptionId());}
}
